BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22441'));
-- keyref is shared across different SAM assets, not a unique identifier.
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code) IN ('HL0330','3A0248') OR source_url ~ '[?&]id=22441(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='51c603c8-9858-412b-a3d3-5eb3f6a661df' OR slug='sam-direct-sale-house-warehouse-office-ban-suan-chonburi-hl0330' OR description ILIKE '%HL0330%' OR (abs(latitude-13.363208337180431)<0.0001 AND abs(longitude-101.0021857853247)<0.0001 AND abs(land_area_sqm-2868)<1)) THEN RAISE NOTICE 'SAM HL0330 or alternate map reference exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, custom_unit_number, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('51c603c8-9858-412b-a3d3-5eb3f6a661df', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'detached_house', 'residence', 'sale', 'whole_property', '28/3', 'ขายตรง SAM บ้านเดี่ยวพร้อมโกดังและสำนักงาน บ้านสวน ชลบุรี 717 ตร.ว. ราคา 18.733 ล้านบาท', 'บ้านเดี่ยวชั้นเดียวเลขที่ 28/3 พร้อมอาคารประกอบ บนที่ดิน 1 ไร่ 3 งาน 17 ตร.ว. หรือ 717 ตร.ว. (2,868 ตร.ม.) ตำบลบ้านสวน อำเภอเมืองชลบุรี จังหวัดชลบุรี โฉนดเลขที่ 45115 จำนวน 1 ฉบับ ราคาประกาศขายจาก SAM 18,733,000 บาท รหัสทรัพย์ HL0330

ที่ดินรูปคล้ายสี่เหลี่ยมผืนผ้า ติดถนน 2 ด้าน ต้นทางระบุด้านทิศตะวันตกกว้างประมาณ 48 เมตร และด้านทิศใต้ลึกสุดประมาณ 68 เมตร ถนนหน้าทรัพย์เป็นทางสาธารณประโยชน์ ผิวคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 8 เมตร อยู่ในเขตผังเมืองสีแดงตามข้อมูล SAM ควรตรวจทิศทางและขนาดแปลงกับโฉนดและผังรังวัด เพราะตัวเลขบนผังภาพประกอบมีรายละเอียดต่างจากข้อความสรุป

รายการสิ่งปลูกสร้างตามทะเบียนที่ SAM รับโอนมี 5 รายการ: บ้านพักอาศัยตึกชั้นเดียวเลขที่ 28/3, ระเบียงบ้าน 2 รายการ, โกดัง และอาคารสำนักงาน ส่วนการสำรวจสภาพทรัพย์ระบุ 3 รายการ ได้แก่ บ้านพักอาศัยตึกชั้นเดียวเลขที่ 28/3, อาคารคอนกรีตเสริมเหล็กชั้นเดียว และอาคารคลังสินค้า

ข้อมูลสำคัญ: SAM ระบุว่าจะโอนให้ผู้ซื้อตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนเท่านั้น รายการทะเบียนกับรายการสำรวจจึงต้องตรวจเทียบให้ตรงกัน รวมทั้งทะเบียนอาคาร แบบแปลน ใบอนุญาต และขอบเขตสิ่งปลูกสร้างที่จะได้รับโอน

ต้นทางระบุว่าอยู่ในย่านที่อยู่อาศัย สาธารณูปโภคครบครัน และเดินทางสะดวก แต่ไม่ได้ระบุกำลังไฟฟ้าหรือรายละเอียดระบบภายใน การมีโกดังและสำนักงานตามทะเบียนไม่ใช่การยืนยันว่าใช้งานเชิงพาณิชย์ได้ทุกประเภท ผู้สนใจควรตรวจข้อกำหนดผังเมืองและใบอนุญาตให้ตรงกับการใช้งานที่ต้องการ

การเดินทาง: จากถนนสุขุมวิท (ทล.3) ใช้ถนนเศรษฐกิจ (ทล.344) มุ่งหน้าถนนเลี่ยงเมืองชลบุรี (ทล.361) เลี้ยวซ้ายเข้าซอยบ้านสวน–เศรษฐกิจ 10 ประมาณ 1 กิโลเมตร จากนั้นเลี้ยวขวาประมาณ 170 เมตร ทรัพย์อยู่ด้านขวามือ สถานที่ใกล้เคียงที่ SAM ระบุ ได้แก่ โรงเรียนเมรี่อิมมาคุเลตคอนแวนต์ วิทยาลัยอาชีวศึกษาชลบุรี ไทวัสดุ ชลบุรี และศูนย์ฝึกอบรมตำรวจภูธรภาค 2

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อฝ่ายขาย SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส HL0330 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม และเงื่อนไขล่าสุด

ใช้พิกัดผู้ดูแล 13.363208337180431, 101.0021857853247 ซึ่งใกล้เคียงหมุดต้นทาง ภาพ SAM แสดงวันที่ 9 กรกฎาคม 2567 เป็นภาพภายนอก แนวรั้ว ทางเข้า ผังแปลง ผังอาคาร และแผนที่ ไม่มีภาพภายใน ต้นทางไม่ระบุจำนวนห้องนอน ห้องน้ำ พื้นที่ใช้สอย จำนวนที่จอดรถ อายุอาคาร หรือสถานะผู้ครอบครอง จึงควรนัดตรวจสภาพปัจจุบันกับ SAM

หมายเหตุแหล่งภาพ: ชื่อไฟล์แผนที่มีรหัส 3A0248 ในวงเล็บ ขณะที่หน้าประกาศและภาพทรัพย์ใช้ HL0330 ให้ใช้อ้างอิงรหัส HL0330 และหน้า id 22441 เมื่อติดต่อ SAM และขอให้ยืนยันความเกี่ยวข้องของรหัสในแผนที่', 18733000, false, 2868, 1, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '28/3 เข้าจากซอยบ้านสวน–เศรษฐกิจ 10', 'เข้าซอยประมาณ 1 กม. แล้วเลี้ยวขวาประมาณ 170 ม.', 'ซอยบ้านสวน–เศรษฐกิจ 10', 13.363208337180431, 101.0021857853247, 'ชลบุรี', 'เมืองชลบุรี', 'บ้านสวน', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-house-warehouse-office-ban-suan-chonburi-hl0330') RETURNING id INTO property_listing_id;
