INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22441&keyref=6007623', 'HL0330', now(), 'Official SAM page captured 2026-09-11. Direct sale THB 18,733,000, 717 sq.wah. Five registered acquired items versus three surveyed buildings; registered-only transfer disclosed. Plot measurements need title/survey confirmation. Nine original exterior/access/plan images retained; property photos display 2024-07-09. No interior photos, occupancy or usable area published. Map filename includes 3A0248; alternate reference recorded without treating it as proven identity. Duplicate search uses code, page ID, deeds, address, area and nearby coordinates across all statuses. Shared keyref is not a property identifier.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: House with Warehouse and Office, Ban Suan, THB 18.733M', 'Single-storey detached house at 28/3 with ancillary buildings in Ban Suan, Mueang Chon Buri, Chon Buri. One title deed, no. 45115, covers 1 rai 3 ngan 17 sq.wah, equivalent to 717 sq.wah or 2,868 sq.m. SAM announced price THB 18,733,000; asset HL0330.

The roughly rectangular plot fronts two roads. SAM''s text states approximately 48 metres on the west and a maximum depth of approximately 68 metres on the south. The public concrete road is approximately six metres wide within an eight-metre right of way. SAM reports red planning zoning. Check the dimensions and directions against the title and survey because the illustration contains measurements that differ from the summary.

Registered structures acquired by SAM: single-storey house 28/3; two separately listed house verandas; a warehouse; and an office. The survey instead lists three structures: single-storey house 28/3, a single-storey reinforced-concrete building and a warehouse. SAM states that transfer follows only its registered acquisition inventory. Verify the building registration, plans, permits and exact structures included.

SAM describes residential surroundings, available utilities and convenient transport, but publishes no electrical capacity or internal system details. Registered warehouse and office structures do not establish permission for every commercial use; confirm the applicable planning provisions and permits.

From Sukhumvit Road (Highway 3), take Setthakit Road (Highway 344) toward the Chon Buri bypass (Highway 361). Turn left into Ban Suan–Setthakit Soi 10 for approximately one kilometre, then right for approximately 170 metres. The property is on the right. Source-listed nearby places include Mary Immaculate Convent School, Chonburi Vocational College, Thai Watsadu Chonburi and Provincial Police Region 2 Training Center.

SAM showed direct-purchase status and this announced price on 11 September 2026. Contact SAM Sales at 02-686-1888, sales@sam.or.th or LINE @samline, quoting HL0330, to confirm availability, price, viewing and current terms.

Administrator coordinates are used. Source photographs display 9 July 2024 and show only the exterior, boundary walls and access, plus plot/building plans and a navigation map. Interior photographs, bedroom and bathroom counts, usable area, parking capacity, building age and occupancy status are not published. Arrange a current inspection.

